	if (alpha.length !== d || alpha.some((row) => row.length !== d)) throw new Error(`${label}: alpha 须为 ${d}×${d} 方阵`);
	for (const m of mu) {
		if (!Number.isFinite(m)) throw new Error(`${label}: μ 各分量须为有限数`);
		if (requirePositiveMu ? !(m > 0) : !(m >= 0)) throw new Error(`${label}: μ 各分量 ${requirePositiveMu ? ">" : "≥"} 0 必需`);
	}
	for (const row of alpha) for (const a of row) if (!Number.isFinite(a) || a < 0) throw new Error(`${label}: alpha 各元素须为非负有限数`);
