			const bRaw = new Array(q).fill(0);
			for (let j = 0; j < q; j += 1) {
				let s = 0;
				const row = wy.matrix[j];
				for (let b2 = 0; b2 < ry; b2 += 1) s += row[b2] * w[b2];
				bRaw[j] = s;
			}
