			feedback: compare("feedback", asPairs(source.getAllDecisionFeedback(), (f) => f.id), asPairs(target.getAllDecisionFeedback(), (f) => f.id)),
			semantic: compare("semantic", asPairs(source.getAllSemanticMemories(), (m) => m.id), asPairs(target.getAllSemanticMemories(), (m) => m.id)),
			procedural: compare("procedural", asPairs(source.getAllProceduralMemories(), (p) => p.id), asPairs(target.getAllProceduralMemories(), (p) => p.id))
