	let v = samples.reduce((s, x) => s + x, 0) / m;
	values[n - 1] = v;
	for (let k = n - 1; k >= 1; k -= 1) {
		v = samples.reduce((s, x) => s + Math.max(x, v), 0) / m;
		values[k - 1] = v;
	}
