	if (!Number.isFinite(threshold) || threshold <= 0) throw new Error(`wolfLyapunov: replacementThreshold 须为正数（得到 ${String(threshold)}）`);
	const meanGap = Math.max(1, Math.floor(options?.meanGap ?? 5));
	const trackCount = Math.max(1, Math.min(options?.tracks ?? 3, 12));
	const n = series.length;
	if (n < 32) return void 0;
	for (const v of series) if (!Number.isFinite(v)) return void 0;
	let lo = Number.POSITIVE_INFINITY;
	let hi = Number.NEGATIVE_INFINITY;
	for (const v of series) {
		if (v < lo) lo = v;
		if (v > hi) hi = v;
	}
	const diameter = hi - lo;
	if (!(diameter > 1e-12)) return void 0;
	const replaceAt = threshold * diameter;
