/** 内核旗标总览（50 旗标开关态；enabled 仅在显式 === true 时为真——缺省关闭） */
function kernelFlagOverview(kernels) {
	const flags = KERNEL_FLAGS.map((meta) => ({
		...meta,
		enabled: kernels?.[meta.name]?.enabled === true
	}));
	const enabled = flags.filter((f) => f.enabled).length;
	return {
		total: flags.length,
		enabled,
		disabled: flags.length - enabled,
		flags
	};
}
