		tools,
		sentinel,
		modelScheduler,
		taskExecutor,
		memory,
		llm,
		tenantManager,
		sync,
		raft,
		hotReload,
		broadcaster,
		benchmark,
		cryptoEngine,
		decisionEngine,
		reflectionEngine,
		optimizer,
		reflector,
		goalEngine,
		metaCognition,
		strategyEvolution,
		selfModel,
		metaController,
		autonomyLoop,
		worldModel,
		curiosity,
		governor,
		hostFusion,
		pipelineAudit,
